function CareerMirror(){const [role,setRole]=useState('Data Analyst');const {data,loading,error}=useAsync(()=>api('/innovation/career-mirror?target_role='+encodeURIComponent(role)),[role]);if(loading)return <Loading/>;if(error)return <ErrorBox text={error}/>;return <><Title eyebrow="NOW ↔ TARGET" title="Career Mirror" sub="Compare your stored evidence with skills demanded by real open opportunities."><select value={role} onChange={e=>setRole(e.target.value)}><option>Data Analyst</option><option>Software Developer</option><option>AI Engineer</option></select></Title><div className="panel">{data.skills.map(x=><div className="gapRow" key={x.skill}><div><b>{x.skill}</b><span>Level {x.current}/4 → {x.target}/4</span></div><div className="bar"><i style={{width:(x.current/4*100)+'%'}}/></div><strong>{x.gap?'Gap '+x.gap:'Ready'}</strong></div>)}</div></>}

function SkillGraph(){const [role,setRole]=useState('Data Analyst');const {data,loading,error}=useAsync(()=>api('/innovation/skill-graph?target_role='+encodeURIComponent(role)),[role]);if(loading)return <Loading/>;if(error)return <ErrorBox text={error}/>;return <><Title eyebrow="INTERACTIVE LEARNING INTELLIGENCE" title="Skill Dependency Graph" sub="A dynamic learning sequence based on your target role and current skills."><select value={role} onChange={e=>setRole(e.target.value)}><option>Data Analyst</option><option>Software Developer</option><option>AI Engineer</option></select></Title><div className="skillGraph">{data.nodes.map((n,i)=><div className="graphNode" key={n.name}><div className="scoreCircle">{n.level||0}</div><b>{n.name}</b><small>{n.status}</small>{i<data.nodes.length-1&&<I.ChevronDown/>}</div>)}</div></>}

function CareerTwin(){const [q,setQ]=useState('Would I qualify for a Data Analyst internship?'),[ans,setAns]=useState(null),[loading,setLoading]=useState(false);const ask=async()=>{setLoading(true);try{setAns(await api('/innovation/career-twin',{method:'POST',body:JSON.stringify({question:q})}))}catch(e){setAns({answer:e.message,readiness:0})}finally{setLoading(false)}};return <><Title eyebrow="DIGITAL CAREER TWIN" title="Career Twin" sub="Ask an evidence-based version of your professional profile."><Button className="primary" onClick={ask} loading={loading}>Ask my Twin <I.Bot/></Button></Title><div className="panel twin"><div className="aiLogo"><I.Bot/></div><div><h3>Evidence-based career answers</h3><input value={q} onChange={e=>setQ(e.target.value)}/>{ans&&<div className="aiFeedback"><b>Readiness: {ans.readiness}%</b><p>{ans.answer}</p><b>Evidence</b>{(ans.evidence||[]).map(x=><div key={x}>{x}</div>)}<b>Actions</b>{(ans.actions||[]).map(x=><div key={x}>• {x}</div>)}</div>}</div></div></>}

function GrowthSimulator(){const [project,setProject]=useState(0),[intern,setIntern]=useState(0),[interview,setInterview]=useState(0),[d,setD]=useState(null);useEffect(()=>{api('/innovation/growth-simulator',{method:'POST',body:JSON.stringify({projects:project,internships:intern,interviews:interview})}).then(setD)},[project,intern,interview]);return <><Title eyebrow="CAREER STRATEGY" title="Growth Simulator" sub="Simulate how evidence-building actions could change your readiness score."/><div className="grid2"><div className="panel"><label className="wideLabel">Portfolio projects: {project}<input type="range" min="0" max="4" value={project} onChange={e=>setProject(+e.target.value)}/></label><label className="wideLabel">Internship experience: {intern}<input type="range" min="0" max="1" value={intern} onChange={e=>setIntern(+e.target.value)}/></label><label className="wideLabel">Interview practice: {interview}<input type="range" min="0" max="4" value={interview} onChange={e=>setInterview(+e.target.value)}/></label></div>{d&&<div className="resultHero"><div className="scoreCircle big">{d.simulated}</div><div><div className="eyebrow">SIMULATED READINESS</div><h2>{d.simulated}%</h2><p>Change from current evidence: +{d.delta} points.</p><b>{d.recommendation}</b></div></div>}</div></>}

function Institution({notify}){const {data:d,loading,error}=useAsync(()=>api('/institution/overview'),[]);const [cur,setCur]=useState(null),[loadingCur,setLoadingCur]=useState(false);const translate=async()=>{setLoadingCur(true);try{setCur(await api('/institution/curriculum-translator'))}catch(e){notify(e.message,'err')}finally{setLoadingCur(false)}};if(loading)return <Loading/>;if(error)return <ErrorBox text={error}/>;return <><Title eyebrow="ACADEMIA INTELLIGENCE" title="Institution Hub" sub="Live institution metrics and AI curriculum intelligence."><Button className="primary" onClick={translate} loading={loadingCur}>Generate curriculum insight <I.Sparkles/></Button></Title><div className="statGrid"><div className="stat"><b>{d.students}</b><small>students</small></div><div className="stat"><b>{d.applications}</b><small>applications</small></div><div className="stat"><b>{d.open_opportunities}</b><small>open opportunities</small></div><div className="stat"><b>{d.assessment_attempts}</b><small>assessment attempts</small></div></div><div className="grid2"><div className="panel"><h3>Demand signals</h3>{d.top_skills.map(x=><div className="gapRow" key={x.skill}><b>{x.skill}</b><div className="bar"><i style={{width:Math.min(100,x.holders*15+20)+'%'}}/></div><strong>{x.holders}</strong></div>)}</div><div className="panel"><h3>Institution actions</h3><div className="listItem"><I.Users/> Identify students who need targeted support</div><div className="listItem"><I.BriefcaseBusiness/> Coordinate placement opportunities</div><div className="listItem"><I.BookOpen/> Translate employer demand into curriculum modules</div></div></div>{cur&&<div className="panel" style={{marginTop:20}}><div className="eyebrow">AI CURRICULUM TRANSLATOR</div><h3>Priority skills</h3><div className="skillTags">{cur.priority_skills.map(x=><span key={x}>{x}</span>)}</div><h3>Recommended modules</h3>{cur.modules.map((m,i)=><div className="listItem" key={i}><I.CheckCircle2/><div><b>{m.name}</b><p>{m.reason}</p><small>Activities: {(m.activities||[]).join(', ')}</small></div></div>)}</div>}</>}

function Form({form,setForm,fields}){return <div className="formGrid">{fields.map(k=><label key={k}>{k.replaceAll("_"," ")}{["description","bio","summary","skills","education","experience","projects","links"].includes(k)?<textarea value={form[k]||""} onChange={e=>setForm({...form,[k]:e.target.value})}/>:<input value={form[k]||""} onChange={e=>setForm({...form,[k]:e.target.value})}/>}</label>)}</div>}
function Modal({title,close,children}){return <div className="modalBack"><div className="modal"><div className="modalHead"><h3>{title}</h3><button className="icon" onClick={close}><I.X/></button></div>{children}</div></div>}
createRoot(document.getElementById("root")).render(<BrowserRouter><App/></BrowserRouter>);
